<script setup lang="ts">import { onMounted, ref } from "vue"; import { accountApi } from "../../api/account"; import { useAuthStore } from "../../stores/auth"; import { ElMessage, ElMessageBox } from "element-plus"; import { HttpError } from "../../shared/http"; import type { AccountUser } from "../../types/account"; const auth=useAuthStore(), rows=ref<AccountUser[]>([]); async function load(){rows.value=(await accountApi.registrations()).items} async function review(row:AccountUser,ok:boolean){try{let note:string|undefined; if(!ok){note=(await ElMessageBox.prompt('拒绝原因','拒绝')).value} await accountApi.review(row.id,ok,note);await load()}catch(e){if(e instanceof HttpError)ElMessage.error(e.status===409?'该注册申请状态已发生变化，请刷新后查看最新状态。':e.response.message)}} onMounted(load)</script><template><el-card><h2>注册审批</h2><el-table :data="rows"><el-table-column prop="username" label="用户名"/><el-table-column prop="user_status" label="状态"/><el-table-column prop="reviewed_at" label="审批时间"/><el-table-column prop="review_note" label="审批说明"/><el-table-column label="操作"><template #default="{row}"><template v-if="row.user_status==='PENDING'&&auth.hasPermission('system:registration:review')"><el-button @click="review(row,true)">批准</el-button><el-button @click="review(row,false)">拒绝</el-button></template></template></el-table-column></el-table></el-card></template>
